import type { ParsedJourney } from "../parser/journey.js";

const INTRO =
  "User intentions and journeys of this project, anchored to the code. Generated by `@vaubaan/harness` from `docs/journeys/*.md`: edit the journeys, not this file, then run `npx @vaubaan/harness update .`.";

/**
 * `docs/journeys/README.md`: every journey (sorted by file name) and its
 * whole tree, one line per node with its effective status, the actors on
 * the journey line (docs/spec/coding-agent-harness.md §9.1.3).
 */
export function buildJourneysIndex(journeys: ReadonlyArray<ParsedJourney>): string {
  const lines = ["# Journeys", "", INTRO, ""];
  const sorted = [...journeys].sort((a, b) => (a.file < b.file ? -1 : a.file > b.file ? 1 : 0));
  for (const journey of sorted) {
    const status = journey.meta?.status ?? "proposed";
    const actors = journey.meta?.actors.join(", ") ?? "";
    lines.push(`- [${journey.title}](./${journey.file}) — ${status} · ${actors}`);
    for (const node of journey.nodes) {
      lines.push(`${"  ".repeat(node.level)}- ${node.title} — ${node.effectiveStatus ?? status}`);
    }
  }
  return `${lines.join("\n")}\n`;
}
